import { normalizeTimePeriodType } from 'utils/timePeriod/timePeriodAvailability';

import { FilterConfig } from '../types';

export const timePeriodFieldFilterConfig: FilterConfig = {
  key: 'time_period',
  order: 15,
  calculator: () => null,
  validator: (filterData) =>
    Boolean(
      filterData.time_period?.enabled && filterData.time_period.values?.length,
    ),

  metadata: {
    displayName: 'Time Period',
    description: 'Visual time period selector field',
  },
};

export const periodTypeFilterConfig: FilterConfig = {
  key: 'period_type',
  order: 15,
  isCommon: true,
  calculator: (filterData) =>
    filterData.time_period?.enabled
      ? (filterData.time_period.default?.value ?? null)
      : null,
  validator: (filterData, value) => {
    const normalizedValue = normalizeTimePeriodType(String(value ?? ''));

    return (
      filterData.time_period?.values?.some(
        (opt) =>
          normalizeTimePeriodType(String(opt?.value ?? '')) === normalizedValue,
      ) ?? false
    );
  },
  metadata: {
    displayName: 'Time Period',
    description: 'Time period type selector (YTD, HALF, QTR, R3M, MTH, FY)',
  },
  dependencies: ['dt_end'],
};
